const DEFAULT_URL = 'ws://127.0.0.1:19876'
const REQUEST_TIMEOUT = 120_000

// ===== Gateway authentication (see backend gateway/ws_server.py) =====
// The token is generated by the backend and persisted to ~/.pebble/gateway.token.
// Dev (vite) injects it as window.__PEBBLE_GATEWAY_TOKEN__; the Tauri shell
// provides it via the get_gateway_token command. Loaded lazily and cached.
let _gatewayToken = ''
let _tokenLoaded = false

async function loadGatewayToken(): Promise<void> {
  if (_tokenLoaded) return
  try {
    const w = window as unknown as Record<string, unknown>
    const injected = w.__PEBBLE_GATEWAY_TOKEN__
    if (typeof injected === 'string' && injected) {
      _gatewayToken = injected
    } else if ('__TAURI_INTERNALS__' in window) {
      const { invoke } = await import('@tauri-apps/api/core')
      const t = await invoke<string | null>('get_gateway_token')
      if (t) _gatewayToken = t
    }
    _tokenLoaded = true
  } catch (e) {
    console.warn('[WS] gateway token unavailable; will retry on next connect', e)
  }
}

export interface GatewayEvent { type: string; payload: Record<string, unknown> }
type EventHandler = (event: GatewayEvent) => void
type StatusHandler = (connected: boolean) => void
type PendingRequest = { resolve: (value: unknown) => void; reject: (err: Error) => void; timeout: ReturnType<typeof setTimeout> }

export class GatewayClient {
  private ws: WebSocket | null = null
  private url: string
  private reqId = 0
  private pending = new Map<string, PendingRequest>()
  private eventHandlers = new Set<EventHandler>()
  private statusHandlers = new Set<StatusHandler>()
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null
  private _connected = false
  private closed = false
  private _lastCloseAt = 0
  private _reconnectCount = 0

  constructor(url?: string) { this.url = url || DEFAULT_URL }

  get connected(): boolean { return this._connected }

  onEvent(handler: EventHandler): () => void {
    this.eventHandlers.add(handler)
    return () => this.eventHandlers.delete(handler)
  }

  onStatus(handler: StatusHandler): () => void {
    this.statusHandlers.add(handler)
    return () => this.statusHandlers.delete(handler)
  }

  connect(): void {
    if (this.ws && (this.ws.readyState === WebSocket.OPEN || this.ws.readyState === WebSocket.CONNECTING)) return
    this.closed = false
    this.connectWithToken()
  }

  private connectWithToken(): void {
    void loadGatewayToken().finally(() => this.doConnect())
  }

  private doConnect(): void {
    try {
      const url = _gatewayToken ? `${this.url}?token=${encodeURIComponent(_gatewayToken)}` : this.url
      const ws = new WebSocket(url)
      this.ws = ws
      ws.onopen = () => {
        this._connected = true
        const gap = this._lastCloseAt ? Date.now() - this._lastCloseAt : 0
        if (gap) console.log(`[WS] reconnected after ${gap}ms`)
        else console.log('[WS] connected')
        this._lastCloseAt = 0
        this._reconnectCount = 0
        for (const h of this.statusHandlers) h(true)
      }
      ws.onmessage = (ev) => {
        try {
          const msg = JSON.parse(ev.data) as Record<string, unknown>
          this.dispatch(msg)
        } catch { /* ignore malformed frame */ }
      }
      ws.onclose = (ev) => {
        if (this.ws !== ws) return
        this._connected = false
        this._lastCloseAt = Date.now()
        if (ev.code === 4401 || ev.code === 4403) {
          console.warn(`[WS] closed (code=${ev.code}): gateway authentication rejected the connection — check that ~/.pebble/gateway.token matches (dev: refresh the page after the backend starts; Tauri: restart the app) and retry`)
        } else {
          console.warn(`[WS] closed (code=${ev.code}, clean=${ev.wasClean}), reconnect in 3s`)
        }
        for (const h of this.statusHandlers) h(false)
        this.rejectAll(new Error('Connection closed'))
        this.scheduleReconnect()
      }
      ws.onerror = () => { console.warn('[WS] error (details via onclose)') }
    } catch (err) {
      this._connected = false
      console.warn('[WS] connect failed', err)
      for (const h of this.statusHandlers) h(false)
      this.scheduleReconnect()
    }
  }

  private scheduleReconnect(): void {
    if (this.closed) return
    if (this.reconnectTimer) return
    this._reconnectCount++
    const n = this._reconnectCount
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null
      if (!this.closed) {
        console.log(`[WS] reconnect attempt #${n}`)
        this.connectWithToken()
      }
    }, 3000)
  }

  disconnect(): void {
    this.closed = true
    if (this.reconnectTimer) { clearTimeout(this.reconnectTimer); this.reconnectTimer = null }
    if (this.ws) { this.ws.onclose = null; this.ws.close(); this.ws = null }
    this._connected = false
    for (const h of this.statusHandlers) h(false)
    this.rejectAll(new Error('Disconnected'))
  }

  private dispatch(msg: Record<string, unknown>): void {
    const id = msg.id as string | undefined
    if (id) {
      const p = this.pending.get(id)
      if (p) {
        clearTimeout(p.timeout)
        this.pending.delete(id)
        if (msg.error) {
          const errMsg = (msg.error as Record<string, unknown>)?.message || 'Request failed'
          p.reject(new Error(String(errMsg)))
        } else {
          p.resolve(msg.result)
        }
        return
      }
    }
    if (msg.method === 'event') {
      const params = msg.params as Record<string, unknown> | undefined
      if (params && typeof params.type === 'string') {
        const ev: GatewayEvent = { type: params.type, payload: (params.payload as Record<string, unknown>) || {} }
        for (const h of this.eventHandlers) h(ev)
      }
    }
  }

  request<T = unknown>(method: string, params: Record<string, unknown> = {}): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      if (!this.ws || this.ws.readyState !== WebSocket.OPEN) { reject(new Error('Not connected')); return }
      const id = `r${++this.reqId}`
      const timeout = setTimeout(() => {
        this.pending.delete(id)
        reject(new Error(`Timeout: ${method}`))
      }, REQUEST_TIMEOUT)
      this.pending.set(id, { resolve: (v) => resolve(v as T), reject, timeout })
      try {
        this.ws.send(JSON.stringify({ id, jsonrpc: '2.0', method, params }))
      } catch (e) {
        clearTimeout(timeout)
        this.pending.delete(id)
        reject(e instanceof Error ? e : new Error(String(e)))
      }
    })
  }

  sendMessage(sessionId: string, text: string, attachments?: Record<string, unknown>[], projectPath?: string): boolean {
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) return false
    const params: Record<string, unknown> = { session_id: sessionId, text }
    if (attachments && attachments.length > 0) params.attachments = attachments
    if (projectPath) params.project_path = projectPath
    try {
      this.ws.send(JSON.stringify({ id: `prompt_${sessionId}`, jsonrpc: '2.0', method: 'prompt.submit', params }))
      return true
    } catch { return false }
  }

  private rejectAll(err: Error): void {
    for (const [, p] of this.pending) { clearTimeout(p.timeout); p.reject(err) }
    this.pending.clear()
  }
}

let _instance: GatewayClient | null = null

export function getGateway(): GatewayClient {
  if (!_instance) _instance = new GatewayClient()
  return _instance
}
